	"id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "oauth_pending_auths_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"user_id" integer NOT NULL CONSTRAINT "oauth_pending_auths_user_id_users_id_fk" REFERENCES "public"."users"("id") ON DELETE cascade ON UPDATE no action,
