-- In-flight authorizations used to live in `oauth_tokens` as a `pending:` marker
-- that overwrote the real token row. Those markers are never written again and a
-- surviving one would read as a connected account, so drop them.
DELETE FROM "oauth_tokens" WHERE "access_token" LIKE 'pending:%';
